local module = {}

local instanceCacheByPath = {}
local instanceCache = {}

module.GetPath = function(instance: Instance)
	local path = ""

	local getPartStr = function(ins)
		local name = ins.Name
		if string.find(name, "@") or string.find(name, "%.") then
			return '["' .. name .. '"]'
		else
			return "." .. name
		end
	end

	while instance do
		if not instance.Parent then
			-- 否则会给出大写的 "Game"
			path = "game" .. path
		else
			path = getPartStr(instance) .. path
		end
		instance = instance.Parent
	end

	return path
end

module.GetPathAndCache = function(instance: Instance)
	local path = instanceCache[instance]
	if path then
		return path
	end

	path = module.GetPath(instance)
	instanceCacheByPath[path] = instance
	instanceCache[instance] = path
	return path
end

module.GetInstanceByPathFromCache = function(path: string)
	return instanceCacheByPath[path]
end

return module
